from core.rules import RuleMachine


class UnsortedTopToEmptyBuffer:
    """Mueve la cima de una pila fuente desordenada a una pila destino vacía para abrir un búfer temporal."""

    name = "unsorted_top_to_empty_buffer"

    def __init__(self, problem, min_bad_on_source=2, min_source_height=2, prefer_larger_top_group=True):
        self.problem = problem
        self.min_bad_on_source = int(min_bad_on_source)
        self.min_source_height = int(min_source_height)
        self.prefer_larger_top_group = bool(prefer_larger_top_group)

    def _is_applicable(self, partial, action):
        so = action.so
        sd = action.sd

        if so == sd:
            return False
        if partial.h(so) < self.min_source_height:
            return False
        if partial.h(sd) != 0:
            return False
        if partial.e(sd) <= 0:
            return False

        bad_on_source = partial.h(so) - partial.sorted_n[so]
        if bad_on_source < self.min_bad_on_source:
            return False

        # Fuente realmente desordenada: la cima pertenece a la zona mala.
        if partial.sorted_n[so] >= partial.h(so):
            return False

        if partial.visited is not None:
            nxt = partial.after(so, sd)
            if nxt in partial.visited:
                return False

        return True

    def allowed(self, partial, memory, candidates):
        allowed = [a for a in candidates if self._is_applicable(partial, a)]
        if not allowed:
            return []

        allowed.sort(key=lambda a: self.score(partial, memory, a))
        return allowed

    def score(self, partial, memory, action):
        so = action.so
        sd = action.sd

        bad_on_source = partial.h(so) - partial.sorted_n[so]
        top_group = partial.g(so)

        primary = -top_group if self.prefer_larger_top_group else top_group
        return (
            primary,                  # aparcar antes grupos "grandes" si se pide
            -bad_on_source,           # prioriza fuentes con más zona mala
            partial.h(so),            # luego fuentes más altas
            sd,                       # desempate estable
            so,
        )


def build_component(
    problem,
    min_bad_on_source=2,
    min_source_height=2,
    prefer_larger_top_group=True,
    **params
):
    rule = UnsortedTopToEmptyBuffer(
        problem,
        min_bad_on_source=min_bad_on_source,
        min_source_height=min_source_height,
        prefer_larger_top_group=prefer_larger_top_group,
    )
    return RuleMachine(problem, [rule])
